scwin.pMenuID = undefined; try { scwin.pMenuID = /* sdd-asis-lifecycle:begin pMenuID — as-is 원문 본문(전환 이관 · 포팅 적용됨) */$c.win.getProgramId()/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf07402' }); }

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
